const rows=[],slug=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,''),maker=name=>/^iPhone/.test(name)?'Apple':/^(PlayStation|PS one|PSP|DualShock|DualSense|Sixaxis)/.test(name)?'Sony':/^Galaxy/.test(name)?'Samsung':name.split(' ')[0];
const add=(cat,source,items)=>items.forEach(([name,year,architecture,summary,specs={}])=>{const base=`x-${cat}-${slug(name)}`,id=rows.some(p=>p.id===base)?`${base}-${year||rows.length}`:base;rows.push({id,name,brand:maker(name),cat,year,architecture,summary,specs,source,note:'Family timeline record. Regional variants, storage capacities, panel revisions and bundled configurations may differ.'})});
